      "campo": "resolucao.antes.formulas",
      "depois": [
        "fragmento menor e mais isolado → menos troca de genes + mais borda → mais perda de espécies",
        "palavra absoluta (\"necessariamente\", \"exclusivamente\") costuma tornar a alternativa falsa"
      ],
      "motivo": "Usa linguagem simples no lugar de seta com símbolos e acrescenta a regra de eliminação usada nos passos."
    },
